SELECT DATE_FORMAT(submit_time, '%x-W%v') AS weekLabel,
       task_type AS taskType,
       ROUND(SUM(correct_count) / NULLIF(SUM(total_count), 0), 2) AS correctRate
FROM user_practice_record
WHERE user_id = #{userId}
  AND submit_time IS NOT NULL
  AND submit_time >= #{startTime}
  AND submit_time < #{endTime}
GROUP BY DATE_FORMAT(submit_time, '%x-W%v'), task_type
ORDER BY weekLabel ASC, taskType ASC
